using Cosmimera.Core.Contracts;

namespace Cosmimera.GameData
{
    /// <summary>
    /// Exponential per-level scale shared by max HP and base damage: 10^((L - 100) / 99), so LV1 = 10% and LV100 = 100%.
    /// REQ: docs/design/level-progression.md#能力值縮放, docs/design/combat.md#傷害公式.
    /// </summary>
    /// <remarks>
    /// Why one curve for both: damage is scaled by the attacker's level and HP by the target's, so a matchup's
    /// damage/HP ratio is Scale(La)/Scale(Ld) = 10^((La - Ld) / 99), a function of the level difference only.
    /// Integer ppm table (generated by tools/balance/level_progression.py) so every client agrees bit-for-bit.
    /// </remarks>
    public static class LevelCurve
    {
        /// <summary>Fixed-point denominator of <see cref="Ppm"/>.</summary>
        /// <remarks>Pre: none. Post: constant. Side effects: none.</remarks>
        public const int PpmOne = 1_000_000;

        // round(10^((L - 100) / 99) * 1e6) for L = 1..100.
        private static readonly int[] Table =
        {
            100000, 102353, 104762, 107227, 109750, 112332, 114976, 117681,
            120450, 123285, 126186, 129155, 132194, 135305, 138489, 141747,
            145083, 148497, 151991, 155568, 159228, 162975, 166810, 170735,
            174753, 178865, 183074, 187382, 191791, 196304, 200923, 205651,
            210490, 215443, 220513, 225702, 231013, 236449, 242013, 247708,
            253536, 259502, 265609, 271859, 278256, 284804, 291505, 298365,
            305386, 312572, 319927, 327455, 335160, 343047, 351119, 359381,
            367838, 376494, 385353, 394421, 403702, 413201, 422924, 432876,
            443062, 453488, 464159, 475081, 486260, 497702, 509414, 521401,
            533670, 546228, 559081, 572237, 585702, 599484, 613591, 628029,
            642807, 657933, 673415, 689261, 705480, 722081, 739072, 756463,
            774264, 792483, 811131, 830218, 849753, 869749, 890215, 911163,
            932603, 954548, 977010, 1000000,
        };

        /// <summary>Scale of <paramref name="level"/> in ppm (<see cref="PpmOne"/> = 1.0).</summary>
        /// <remarks>Pre: 1 &lt;= level &lt;= 100. Post: 100000..PpmOne, strictly increasing, PpmOne at 100. Side effects: none.</remarks>
        public static int Ppm(int level)
        {
            Contract.Requires(level >= 1 && level <= 100, "level must be 1..100");
            return Table[level - 1];
        }

        /// <summary>One LV100 basis value scaled to <paramref name="level"/>: round_half_up(B × Scale(L)).</summary>
        /// <remarks>Pre: 1 &lt;= level &lt;= 100; b &gt;= 0. Post: 0..b, monotone in level, b at 100. Side effects: none.</remarks>
        public static int Scale(int b, int level)
        {
            Contract.Requires(b >= 0, "basis must be >= 0");
            return (int)(((long)b * Ppm(level) + PpmOne / 2) / PpmOne);
        }
    }
}
